#!/usr/bin/env bash
# Generated by aztec-mcp aztec_dev_release on 2026-10-21T12:00:00.000Z.
# Review every value below before you run this script. It spends funds from the
# account named in ACCOUNT.
set -euo pipefail

NODE_URL='https://node.example:8080'
ACCOUNT='alice'
PAYMENT='method=fpc-sponsored,fpc=0xabababababababababababababababababababababababababababababababab'
CONTRACT_ALIAS='token'

WALLET='/opt/aztec/bin/aztec-wallet'
ARTIFACT='/work/project/artifact.json'
EXPECTED_SHA256='0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef'

if command -v sha256sum >/dev/null 2>&1; then
  ACTUAL_SHA256="$(sha256sum "$ARTIFACT" | cut -d' ' -f1)"
else
  ACTUAL_SHA256="$(shasum -a 256 "$ARTIFACT" | cut -d' ' -f1)"
fi
if [ "$ACTUAL_SHA256" != "$EXPECTED_SHA256" ]; then
  echo "Artifact hash changed since packaging. Compile and package again." >&2
  exit 1
fi

"$WALLET" deploy "$ARTIFACT" \
  --node-url "$NODE_URL" \
  --from "$ACCOUNT" \
  --alias "$CONTRACT_ALIAS" \
  --init 'constructor' \
  --args '1000' '7' 'true' \
  --payment "$PAYMENT" \
  --wait-for-status proposed \
  --json
